INSERT INTO public.tools_catalog (id, name, description, category, tool_types, source, is_live, is_premium, is_free, dedicated_route, display_order, extra_categories)
VALUES
  ('financial-life-planner', 'Financial Life Planner', 'A complete money plan for your family: net worth, goals, emergency fund, insurance gaps, investing plan and a year-by-year roadmap.', 'Money & Planning', ARRAY['Financial Planning', 'Planning'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('retirement-readiness-studio', 'Retirement Readiness Studio', 'Find out if you can retire when you want: corpus needed, gap, monthly saving, withdrawal plan and how long the money lasts.', 'Money & Planning', ARRAY['Retirement', 'Planning'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('portfolio-x-ray', 'Portfolio X-Ray', 'Upload your CAS or broker statement to see asset mix, overlap between funds, costs, concentration and an action list to tidy up.', 'Money & Planning', ARRAY['Investments', 'Analytics Tools'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('income-tax-regime-planner', 'Income Tax Regime Planner', 'Compare the old and new tax regimes on your real income and deductions, see the tax under each and a plan to save more.', 'Money & Planning', ARRAY['Income Tax', 'Calculators'], 'featured', true, false, false, NULL, 0, ARRAY['Finance & Accounting']),
  ('bank-statement-analyser', 'Bank Statement Analyser', 'Upload bank or card statements to see where your money goes, recurring payments, leaks, savings rate and a budget that fits.', 'Money & Planning', ARRAY['Budgeting', 'Analytics Tools'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('family-budget-coach', 'Family Budget Coach', 'A friendly coaching session that builds a family budget with you, untangles money worries and leaves you with a monthly plan.', 'Money & Planning', ARRAY['Budgeting', 'Coaching'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('child-education-fund-planner', 'Child Education Fund Planner', 'Plan for your child''s school and college: future cost by course and country, monthly saving needed and a step-down plan as the date nears.', 'Money & Planning', ARRAY['Education', 'Planning'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('insurance-policy-decoder', 'Insurance Policy Decoder', 'Upload a health, life, motor or home policy and get the cover, exclusions, waiting periods, claim steps and gaps in plain words.', 'Money & Planning', ARRAY['Insurance', 'Document Tools'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('health-claim-helper', 'Health Claim Helper', 'Upload a rejected or short-paid health claim and policy to see why, what the policy says, and get an appeal letter and next steps.', 'Money & Planning', ARRAY['Insurance', 'Letters'], 'featured', true, false, false, NULL, 0, ARRAY['Legal & Compliance', 'Health & Wellness']),
  ('debt-freedom-planner', 'Debt Freedom Planner', 'List your loans and cards to get a debt-free date, the best payoff order, monthly plan, interest saved and steps to stop new debt.', 'Money & Planning', ARRAY['Debt', 'Planning'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('home-buying-planner', 'Home Buying Planner', 'Plan a home purchase: what you can afford, full cost with taxes and charges, down payment plan, buy vs rent and a document checklist.', 'Money & Planning', ARRAY['Real Estate', 'Planning'], 'featured', true, false, false, NULL, 0, ARRAY['Home, Family & Travel']),
  ('freelancer-money-studio', 'Freelancer Money Studio', 'Money system for freelancers: pay yourself a salary, tax set-aside, GST check, invoicing rules, emergency fund and pricing.', 'Money & Planning', ARRAY['Freelancing', 'Planning'], 'featured', true, false, false, NULL, 0, ARRAY['Jobs & Careers']),
  ('nri-money-planner', 'NRI Money Planner', 'A money plan for NRIs: NRE vs NRO accounts, sending money home, India investments, property, tax points to check and a return plan.', 'Money & Planning', ARRAY['NRI', 'Planning'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('company-research-report', 'Company Research Report', 'Upload a company''s annual report or results to get an analyst-style report: business, numbers, ratios, risks and questions to ask.', 'Money & Planning', ARRAY['Investments', 'Research'], 'featured', true, false, false, NULL, 0, ARRAY['Finance & Accounting', 'Research']),
  ('mutual-fund-comparator', 'Mutual Fund Comparator', 'Upload factsheets of 2 to 5 funds and compare returns, risk, costs, holdings and fit for your goal in one clear table.', 'Money & Planning', ARRAY['Investments', 'Analytics Tools'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('cash-flow-forecaster', 'Cash Flow Forecaster', 'Upload sales, bills and bank data to get a 13-week cash flow forecast for your business, with the danger weeks and fixes.', 'Finance & Accounting', ARRAY['Cash Flow', 'Forecasting'], 'featured', true, false, false, NULL, 0, ARRAY['Money & Planning', 'Startups & Strategy']),
  ('financial-statement-explainer', 'Financial Statement Explainer', 'Upload a P&L, balance sheet or CA-prepared accounts and get them explained in plain words, with ratios, warnings and questions.', 'Finance & Accounting', ARRAY['Accounting', 'Analytics Tools'], 'featured', true, false, false, NULL, 0, ARRAY['Money & Planning']),
  ('kids-money-course', 'Kids Money Course', 'A 12-week money course for your child, by age: lessons, family activities, pocket money system, games and a savings goal.', 'Money & Planning', ARRAY['Kids', 'Education'], 'featured', true, false, false, NULL, 0, ARRAY['For Students']),
  ('financial-health-check-up', 'Financial Health Check-up', 'Answer 20 questions to get a money health score across saving, debt, protection, investing and planning, with your top 5 fixes.', 'Money & Planning', ARRAY['Financial Planning', 'Assessment'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('side-income-planner', 'Side Income Planner', 'Find side-income ideas that fit your skills, time and money: ranked ideas, startup cost, earnings path and a 30-day start plan.', 'Money & Planning', ARRAY['Side Hustle', 'Planning'], 'featured', true, false, false, NULL, 0, ARRAY['Jobs & Careers'])
